-- CodeLab Project 3: SQL Data Analysis
-- Platform: Microsoft SQL Server / SSMS
-- This script contains the cleaned 1,200-row dataset and the required SQL analysis queries.

IF DB_ID('CodeLab_Project_3') IS NULL
    CREATE DATABASE CodeLab_Project_3;
GO

USE CodeLab_Project_3;
GO

IF OBJECT_ID('dbo.Orders', 'U') IS NOT NULL
    DROP TABLE dbo.Orders;
GO

CREATE TABLE dbo.Orders (
    OrderID NVARCHAR(20) NOT NULL PRIMARY KEY,
    [Date] DATE NOT NULL,
    CustomerID NVARCHAR(20) NOT NULL,
    Product NVARCHAR(100) NOT NULL,
    Quantity INT NOT NULL,
    UnitPrice DECIMAL(10,2) NOT NULL,
    ShippingAddress NVARCHAR(150) NOT NULL,
    PaymentMethod NVARCHAR(50) NOT NULL,
    OrderStatus NVARCHAR(50) NOT NULL,
    TrackingNumber NVARCHAR(30) NOT NULL,
    ItemsInCart INT NOT NULL,
    CouponCode NVARCHAR(50) NOT NULL,
    ReferralSource NVARCHAR(50) NOT NULL,
    TotalPrice DECIMAL(12,2) NOT NULL
);
GO

GO

GO

GO

GO

GO

GO

-- ============================================================
-- PROJECT 3 ANALYSIS QUERIES
-- ============================================================

-- 1. SELECT: view all records
SELECT *
FROM dbo.Orders;
GO

-- 2. SELECT: view selected columns
SELECT OrderID, [Date], Product, Quantity, UnitPrice, TotalPrice
FROM dbo.Orders;
GO

-- 3. WHERE: show shipped orders
SELECT OrderID, Product, Quantity, TotalPrice, OrderStatus
FROM dbo.Orders
WHERE OrderStatus = 'Shipped';
GO

-- 4. WHERE + ORDER BY: orders above 2,000
SELECT OrderID, Product, Quantity, TotalPrice
FROM dbo.Orders
WHERE TotalPrice > 2000
ORDER BY TotalPrice DESC;
GO

-- 5. ORDER BY: highest-value orders first
SELECT OrderID, Product, Quantity, TotalPrice
FROM dbo.Orders
ORDER BY TotalPrice DESC;
GO

-- 6. ORDER BY: products alphabetically
SELECT DISTINCT Product
FROM dbo.Orders
ORDER BY Product;
GO

-- 7. GROUP BY + COUNT: number of orders by product
SELECT Product, COUNT(*) AS OrderCount
FROM dbo.Orders
GROUP BY Product
ORDER BY OrderCount DESC;
GO

-- 8. GROUP BY + SUM: total sales by product
SELECT Product, SUM(TotalPrice) AS TotalSales
FROM dbo.Orders
GROUP BY Product
ORDER BY TotalSales DESC;
GO

-- 9. GROUP BY + AVG: average order value by product
SELECT Product, AVG(TotalPrice) AS AverageOrderValue
FROM dbo.Orders
GROUP BY Product
ORDER BY AverageOrderValue DESC;
GO

-- 10. COUNT: total number of orders
SELECT COUNT(*) AS TotalOrders
FROM dbo.Orders;
GO

-- 11. SUM: total sales
SELECT SUM(TotalPrice) AS TotalSales
FROM dbo.Orders;
GO

-- 12. AVG: average order value
SELECT AVG(TotalPrice) AS AverageOrderValue
FROM dbo.Orders;
GO

-- 13. GROUP BY: orders by payment method
SELECT PaymentMethod, COUNT(*) AS OrderCount
FROM dbo.Orders
GROUP BY PaymentMethod
ORDER BY OrderCount DESC;
GO

-- 14. GROUP BY: sales by order status
SELECT OrderStatus, COUNT(*) AS OrderCount, SUM(TotalPrice) AS TotalSales
FROM dbo.Orders
GROUP BY OrderStatus
ORDER BY TotalSales DESC;
GO

-- 15. GROUP BY: monthly sales by year and month
SELECT YEAR([Date]) AS OrderYear,
       MONTH([Date]) AS OrderMonth,
       SUM(TotalPrice) AS MonthlySales
FROM dbo.Orders
GROUP BY YEAR([Date]), MONTH([Date])
ORDER BY OrderYear, OrderMonth;
GO

-- 16. Highest-selling product by quantity
SELECT TOP 1 Product,
       SUM(Quantity) AS TotalQuantitySold
FROM dbo.Orders
GROUP BY Product
ORDER BY TotalQuantitySold DESC;
GO

-- 17. Dataset check
SELECT COUNT(*) AS TotalRows,
       COUNT(DISTINCT OrderID) AS UniqueOrderIDs,
       MIN([Date]) AS EarliestDate,
       MAX([Date]) AS LatestDate
FROM dbo.Orders;
GO
